 func (s *Server) handleGetSession(w http.ResponseWriter, r *http.Request) {
 	sess, err := s.sessionManager.GetOrCreate(r, w)
 	if err != nil {
 		http.Error(w, "Failed to get session", http.StatusInternalServerError)
 		return
