 		wsService.SetAuthMiddleware(authMiddleware)
 	}
 	wsService.SetSocketDir(s.config.SocketDir)
 	wsService.SetDatabase(s.db)
 	// Wire real Cognitive Engine into WebSocket for live metric broadcasts (Gap 8 + 12)
